package com.example.logger.core.network

sealed class NetworkResult<out T> {
    data class Success<T>(val data: T) : NetworkResult<T>()
    data class Error(
        val message: String? = null,
        val throwable: Throwable? = null,
        val code: Int? = null
    ) : NetworkResult<Nothing>()
}

inline fun <T, R> NetworkResult<T>.map(transform: (T) -> R): NetworkResult<R> = when (this) {
    is NetworkResult.Success -> NetworkResult.Success(transform(data))
    is NetworkResult.Error -> this
}

package com.example.logger.core.network

import com.example.logger.core.exception.AppException

sealed class NetworkResult<out T> {
    data class Success<T>(val data: T) : NetworkResult<T>()
    data class Error(
        val message: String? = null,
        val throwable: Throwable? = null,
        val code: Int? = null
    ) : NetworkResult<Nothing>()
}

inline fun <T, R> NetworkResult<T>.map(transform: (T) -> R): NetworkResult<R> = when (this) {
    is NetworkResult.Success -> NetworkResult.Success(transform(data))
    is NetworkResult.Error -> this
}

package com.example.logger.core.network

import com.example.logger.core.exception.AppException
import retrofit2.HttpException
import java.io.IOException

suspend inline fun <T> safeApiCall(crossinline block: suspend () -> T): T {
    try {
        return block()
    } catch (e: IOException) {
        throw AppException.Network(message = e.message, cause = e)
    } catch (e: HttpException) {
        throw AppException.Server(message = e.message(), cause = e)
    } catch (e: AppException) {
        throw e
    } catch (e: Throwable) {
        throw AppException.Unknown(message = e.message, cause = e)
    }
}

package com.example.logger.core.network

import com.example.logger.core.exception.AppException
import retrofit2.HttpException
import java.io.IOException

suspend inline fun <T> safeApiCall(crossinline block: suspend () -> T): T {
    try {
        return block()
    } catch (e: IOException) {
        throw AppException.Network(message = e.message, cause = e)
    } catch (e: HttpException) {
        throw AppException.Server(message = e.message(), cause = e)
    } catch (e: AppException) {
        throw e
    } catch (e: Throwable) {
        throw AppException.Unknown(message = e.message, cause = e)
    }
}

suspend inline fun <T> safeNetworkCall(crossinline block: suspend () -> T): NetworkResult<T> = try {
    NetworkResult.Success(safeApiCall { block() })
} catch (e: AppException) {
    NetworkResult.Error(message = e.message, throwable = e)
} catch (e: Throwable) {
    NetworkResult.Error(message = e.message, throwable = e)
}

package com.example.logger.data.repository

import com.example.logger.core.exception.AppException
import com.example.logger.core.network.safeApiCall
import com.example.logger.data.mapper.TeamMemberDtoMapper
import com.example.logger.data.remote.api.TeamApiService
import com.example.logger.domain.model.TeamMemberData
import com.example.logger.domain.repository.TeamRepository
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.flow.flow
import javax.inject.Inject

class TeamRepositoryImpl @Inject constructor(
    private val api: TeamApiService,
    private val teamMemberDtoMapper: TeamMemberDtoMapper
) : TeamRepository {
    override fun getTeamMembers(teamId: Long, page: Int, size: Int): Flow<List<TeamMemberData>> =
        flow {
            val response = safeApiCall { api.getTeamMembers(teamId, page, size) }
            val members = response.items.map { teamMemberDtoMapper.map(it) }
            emit(members)
        }
}

package com.example.logger.data.repository

import com.example.logger.core.network.NetworkResult
import com.example.logger.core.network.safeNetworkCall
import com.example.logger.data.mapper.TeamMemberDtoMapper
import com.example.logger.data.remote.api.TeamApiService
import com.example.logger.domain.model.TeamMemberData
import com.example.logger.domain.repository.TeamRepository
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.flow.flow
import javax.inject.Inject

class TeamRepositoryImpl @Inject constructor(
    private val api: TeamApiService,
    private val teamMemberDtoMapper: TeamMemberDtoMapper
) : TeamRepository {
    override fun getTeamMembers(teamId: Long, page: Int, size: Int): Flow<NetworkResult<List<TeamMemberData>>> =
        flow {
            val result = safeNetworkCall { api.getTeamMembers(teamId, page, size) }
            when (result) {
                is NetworkResult.Success -> {
                    val members = result.data.items.map { teamMemberDtoMapper.map(it) }
                    emit(NetworkResult.Success(members))
                }
                is NetworkResult.Error -> emit(result)
            }
        }
}

package com.example.logger.data.team.dto

import com.google.gson.annotations.SerializedName

// DTO for a single team member
data class TeamMemberDto(
    @SerializedName("id") val id: Long,
    @SerializedName("name") val name: String,
    @SerializedName("email") val email: String,
    @SerializedName("createdAt") val createdAt: String,
    @SerializedName("updatedAt") val updatedAt: String
)

// DTO for the paged response
data class TeamMembersResponseDto(
    @SerializedName("items") val items: List<TeamMemberDto>,
    @SerializedName("meta") val meta: MetaDto
)

data class MetaDto(
    @SerializedName("page") val page: Int,
    @SerializedName("size") val size: Int,
    @SerializedName("total") val total: Int
)

package com.example.logger.data.team.remote

import com.example.logger.data.team.dto.TeamMembersResponseDto
import retrofit2.http.GET
import retrofit2.http.Path
import retrofit2.http.Query

interface TeamApiService {
    @GET("standups/teams/{teamId}/members")
    suspend fun getTeamMembers(
        @Path("teamId") teamId: Long,
        @Query("page") page: Int,
        @Query("size") size: Int
    ): TeamMembersResponseDto
}

package com.example.logger.data.team.repository

import com.example.logger.data.team.remote.TeamApiService
import com.example.logger.domain.team.model.TeamMemberData
import com.example.logger.domain.team.repository.TeamRepository
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.flow.flow
import javax.inject.Inject

class TeamRepositoryImpl @Inject constructor(
    private val api: TeamApiService
) : TeamRepository {
    override fun getTeamMembers(teamId: Long, page: Int, size: Int): Flow<List<TeamMemberData>> = flow {
        val response = api.getTeamMembers(teamId, page, size)
        val members = response.items.map {
            TeamMemberData(
                id = it.id,
                name = it.name,
                email = it.email,
                createdAt = it.createdAt,
                updatedAt = it.updatedAt
            )
        }
        emit(members)
    }
}

